<div class="container">
    <div class="grid">
        <div class="cell" data-value="1" data-row="1" data-col="1"></div>
        <div class="cell" data-value="2" data-row="1" data-col="2"></div>
        <!-- ... fill the grid with pre-filled cells and random numbers -->
    </div>
</div>
<div>
    <input type="text" id="inputCell" disabled>
    <button onclick="changeCell()">Inserisci</button>
    <button onclick="clearCell()">Cancella</button>
    <button onclick="reset()">Nuova Partita</button>
</div>
<script>
// Initialize the grid with pre-filled cells and random numbers
function initGrid() {
    const grid = document.querySelector(".grid");
    for (let i = 0; i < 81; i++) {
        const cell = document.createElement("div");
        cell.classList.add("cell");
        grid.appendChild(cell);
        if (i % 9 === 0 && i !== 0) {
            const row = i / 9;
            const col = i % 9;
            grid.insertAdjacentElement("afterbegin", document.createElement("div"));
        }
        if (i < 10) {
            const value = document.createElement("div");
            value.classList.add("value");
            cell.appendChild(value);
        } else if (i < 100) {
            const value = document.createElement("input");
            value.classList.add("value");
            value.type = "number";
            value.value = i - 9;
            value.addEventListener("change", function() {
                this.closest(".cell").querySelector("input[type='text']").value = this.value;
            });
            cell.appendChild(value);
        }
    }
    grid.querySelectorAll("input[type='number']").forEach(cell => {
        const value = cell.value || cell.value === 0 ? parseInt(cell.value) : 0;
        if (value === 0) {
            cell.style.backgroundColor = "#fff";
            cell.style.color = "#000";
        }
    });
}

// Change the selected cell
function changeCell() {
    const inputCell = document.getElementById("inputCell");
    const selectedCell = document.querySelector(".cell");
    selectedCell.classList.add("selected");
    selectedCell.querySelector("input[type='text']").value = selectedCell.querySelector("input[type='number']").value;
    selectedCell.querySelector("input[type='number']").value = "";
}

// Clear the selected cell
function clearCell() {
    const selectedCell = document.querySelector(".cell");
    selectedCell.querySelector("input[type='number']").value = "";
    selectedCell.classList.remove("selected");
}

// Reset the grid
function reset() {
    const grid = document.querySelector(".grid");
    grid.innerHTML = "";
    initGrid();
}

// Initialize the grid on page load
initGrid();
</script>
